301	func decodeAPIError(t *testing.T, body []byte) testAPIError {
302		t.Helper()
303		var envelope testAPIEnvelope
304		if err := json.Unmarshal(body, &envelope); err != nil {
305			t.Fatalf("decode error envelope: %v", err)
306		}
307		if envelope.Success {
308			t.Fatalf("expected error envelope, got body=%s", string(body))
309		}
310		if envelope.Error == nil {
311			t.Fatalf("expected error body, got body=%s", string(body))
312		}
313		return *envelope.Error
314	}
